set +e
# poster1-undo (generated by make_guests.py from block-*.py; see those files for what and why)
fsck.hfsplus -f -n /dev/vda | tail -2
mount -t hfsplus -o rw,force /dev/vda /work/root || exit 1
python3 - <<'GUEST'
UNDO=True
# poster1: PosterBoard (iOS 16 lock-screen posters, home wallpaper, lock-screen widgets gallery) is a LaunchAngel
# (/System/Library/LaunchAngels/com.apple.PosterBoard.plist, ProgramArguments /Applications/PosterBoard.app/PosterBoard).
# On iOS its sandbox profile puts HOME in its data container; with the port's permissive "Sandbox" policy the container
# op returns ENOENT, so PosterBoard runs with HOME=/var/mobile:
#   * its data store is /var/mobile/Library/Application Support/PRBPosterExtensionDataStore (59/Extensions is EMPTY:
#     no poster provider was ever recorded), and 18 crash logs show the first-time setup trapping in
#     -[PBFPosterExtensionDataStore _stateLock_setupSwitcherConfigurationForFirstTime] (last on 2026-11-08);
#   * every boot it deletes FOREIGN folders in the shared /var/mobile/Library/Application Support
#     (kernel 'SWEET FS: PosterBoard[...] unlink': com.apple.remotemanagementd RMAdminStore DBs, com.apple.ap.adprivacyd,
#     com.apple.ProtectedCloudStorage key DBs), i.e. data of other daemons.
# This block gives the job HOME / CFFIXED_USER_HOME / TMPDIR = its existing data container (found by the MCM metadata,
# exactly one allowed) in /System/Library/xpc/launchd.plist (Metal receipt installed_launchd_sha256 checked before and
# updated after, as guest-gnssd3.sh), and moves the old data store to /private/var/db/nord2-stock/poster1/ (kept, not
# deleted) so PosterBoard rebuilds it - with the providers - inside its container. Undo restores the exact job and data.
import os, json, glob, hashlib, plistlib, shutil
R='/work/root'; LP='/System/Library/xpc/launchd.plist'; MR='/private/var/db/nord2-metal/receipt.json'
KEY='/System/Library/LaunchAngels/com.apple.PosterBoard.plist'; PROG=['/Applications/PosterBoard.app/PosterBoard']
D='/private/var/db/nord2-stock'; REC=D+'/poster1.json'; BK=D+'/poster1'
OLDSTORE='/private/var/mobile/Library/Application Support/PRBPosterExtensionDataStore'
sha=lambda b: hashlib.sha256(b).hexdigest(); rd=lambda p: open(R+p,'rb').read()
def put(path, data, mode, uid, gid):
    tmp=R+path+'.nord2tmp'
    if os.path.lexists(tmp): os.remove(tmp)
    with open(tmp,'xb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
    os.chmod(tmp,mode); os.chown(tmp,uid,gid); os.replace(tmp,R+path)
    assert rd(path)==data
def container():
    hits=[]
    for m in glob.glob(R+'/private/var/mobile/Containers/Data/Application/*/.com.apple.mobile_container_manager.metadata.plist'):
        try:
            if plistlib.load(open(m,'rb')).get('MCMMetadataIdentifier')=='com.apple.PosterBoard': hits.append(os.path.dirname(m)[len(R):])
        except Exception: pass
    return hits
raw=rd(LP); fmt=plistlib.FMT_BINARY if raw[:6]==b'bplist' else plistlib.FMT_XML; cfg=plistlib.loads(raw)
rc=json.load(open(R+MR)); oldh=rc.get('installed_launchd_sha256')
def save_launchd(tag):
    out=plistlib.dumps(cfg,fmt=fmt,sort_keys=False); lst=os.stat(R+LP)
    put(LP,out,lst.st_mode&0o7777,lst.st_uid,lst.st_gid); assert plistlib.loads(rd(LP))==cfg
    rc['installed_launchd_sha256']=sha(out); mst=os.stat(R+MR)
    put(MR,(json.dumps(rc,indent=2)+'\n').encode(),mst.st_mode&0o7777,mst.st_uid,mst.st_gid)
    print('POSTER1_LAUNCHD', tag, oldh[:12], '->', rc['installed_launchd_sha256'][:12])
job=cfg.get('LaunchDaemons',{}).get(KEY)
if oldh!=sha(raw): print('POSTER1_REFUSED launchd.plist differs from the Metal receipt: not touching it')
elif not isinstance(job,dict) or job.get('ProgramArguments')!=PROG: print('POSTER1_REFUSED PosterBoard job not found / unexpected')
elif not UNDO:
    rec=json.load(open(R+REC)) if os.path.exists(R+REC) else None
    hits=container()
    if len(hits)!=1: print('POSTER1_REFUSED %d PosterBoard data containers'%len(hits))
    else:
        C=hits[0]
        env={'HOME':C,'CFFIXED_USER_HOME':C,'TMPDIR':C+'/tmp/'}
        if rec is None:
            rec={'job_before':job.get('EnvironmentVariables'),'container':C,'store_moved':False,'made':[]}
        for sub in ('Library','Library/Application Support','tmp'):
            if not os.path.isdir(R+C+'/'+sub):
                os.makedirs(R+C+'/'+sub); os.chown(R+C+'/'+sub,501,501); os.chmod(R+C+'/'+sub,0o755); rec['made'].append(sub)
        if os.path.isdir(R+OLDSTORE) and not os.path.lexists(R+BK+'/PRBPosterExtensionDataStore'):
            os.makedirs(R+BK,exist_ok=True); os.rename(R+OLDSTORE,R+BK+'/PRBPosterExtensionDataStore'); rec['store_moved']=True
        os.makedirs(R+D,exist_ok=True); json.dump(rec,open(R+REC,'w'),indent=1)
        newenv=dict(job.get('EnvironmentVariables') or {}, **env)
        if job.get('EnvironmentVariables')!=newenv:
            job['EnvironmentVariables']=newenv; save_launchd('env set %s'%C)
        else: print('POSTER1_LAUNCHD already')
        print('POSTER1_INSTALL container', C, 'store_moved', rec['store_moved'])
else:
    rec=json.load(open(R+REC)) if os.path.exists(R+REC) else None
    if rec is None: print('POSTER1_UNDO nothing to undo')
    else:
        if rec['job_before'] is None: job.pop('EnvironmentVariables',None)
        else: job['EnvironmentVariables']=rec['job_before']
        save_launchd('env restored')
        C=rec['container']; new=R+C+'/Library/Application Support/PRBPosterExtensionDataStore'
        if os.path.isdir(new):   # what PosterBoard built in the container is kept for inspection, not deleted
            os.makedirs(R+BK,exist_ok=True); dst=R+BK+'/container-store-at-undo'
            if os.path.lexists(dst): shutil.rmtree(dst)
            os.rename(new,dst); print('POSTER1_UNDO container store kept at', dst[len(R):])
        if rec['store_moved'] and os.path.isdir(R+BK+'/PRBPosterExtensionDataStore') and not os.path.lexists(R+OLDSTORE):
            os.rename(R+BK+'/PRBPosterExtensionDataStore',R+OLDSTORE)
        for sub in reversed(rec['made']):
            p=R+C+'/'+sub
            if os.path.isdir(p) and not os.listdir(p): os.rmdir(p)
        os.remove(R+REC)
        if os.path.isdir(R+BK) and not os.listdir(R+BK): os.rmdir(R+BK)
        if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
        print('POSTER1_UNDO done')
os.sync()
GUEST
echo 'CC_JOB_ADDED poster1-undo'
echo 'CC_RECEIPT_UPDATED metal receipt launchd sha'
sync
umount /work/root
fsck.hfsplus -f -n /dev/vda
echo INSTALL_DONE
